  settings_search_idx_fda: 'macOS가 Xenon의 전체 디스크 접근 권한을 해제했습니다. 권한이 앱 서명에 묶여 있어 업데이트할 때마다 일어납니다. 권한이 없는 동안 Xenon은 홈 폴더를 색인하지 않습니다. 그렇지 않으면 스캔할 때마다 데스크탑, 서류, 다운로드, 사진, 음악에 대한 권한 요청이 반복됩니다. 시스템 설정 → 개인정보 보호 및 보안 → 전체 디스크 접근 권한에서 Xenon을 목록에서 제거한 뒤 다시 추가하세요.',
