  streaming_discord_desc: 'Deck에서 Discord 음성을 제어하려면 계정을 연결하세요(음소거, 소리 차단, 채널 참가/나가기).',
  streaming_setup_discord: 'Discord 앱을 만들고(개발자 포털) OAuth2에 리디렉션 http://localhost 을 추가한 뒤 Client ID와 Client Secret을 여기에 붙여넣으세요. Discord 데스크톱 클라이언트가 실행 중이어야 합니다.',
