  streaming_discord_notrunning: 'Discord 데스크톱 앱이 감지되지 않았습니다. Discord를 열고 다시 시도하세요.',
  streaming_discord_busy: 'Discord 로컬 연결이 사용 중입니다(다른 앱이 사용 중일 수 있음). 잠시 후 다시 연결을 시도하세요.',
  streaming_discord_pipedenied: 'Discord가 관리자 권한으로 실행 중이어서 Xenon이 통신할 수 없습니다. Discord를 완전히 종료한 뒤(트레이 아이콘 → 종료) 일반 권한으로 다시 열고 연결을 누르세요. 기다려도 해결되지 않습니다.',
  streaming_discord_closed: 'Discord가 연결을 종료했습니다. 클라이언트 ID가 올바른지, 그리고 이 애플리케이션을 만든 계정으로 Discord 데스크톱 앱에 로그인되어 있는지 확인하세요.',
  streaming_discord_denied: 'Discord에서 인증이 거부되었습니다. 요청을 승인하고, 이 애플리케이션을 소유한 계정으로 로그인되어 있는지 확인하세요.',
  streaming_discord_timeout: '인증 창이 시간 초과되었습니다. 다시 시도하고 Discord에서 "승인"을 빠르게 클릭하세요.',
  streaming_token_failed: '코드 교환 중 로그인에 실패했습니다. 클라이언트 시크릿과 리디렉션 URL이 정확히 http://localhost인지 확인하세요.',
  streaming_discord_inflight: '이미 승인을 기다리는 로그인이 있습니다. Discord에서 팝업을 확인하거나(또는 시간이 초과될 때까지 기다린 뒤) 다시 시도하세요.',
  streaming_discord_badclientid: 'Discord가 Client ID를 거부했습니다. 개발자 포털에서 앱의 General Information 페이지에 있는 "Application ID"를 복사하여 자격 증명 편집에서 다시 입력하세요.',
  streaming_discord_authfailed: 'Discord가 인증을 거부했습니다. Discord 데스크톱 앱은 개발자 포털에서 이 애플리케이션을 소유한 것과 동일한 계정으로 로그인되어 있어야 합니다.',
  streaming_discord_invalidscope: 'Discord가 요청한 권한을 거부했습니다. 여기에 필요한 "rpc" 접근 권한은 이 애플리케이션을 소유한 계정(또는 앱의 OAuth2 테스터로 추가한 계정)에만 부여됩니다. Discord 데스크톱 앱이 어떤 계정으로 로그인되어 있는지 확인하세요. 앱이 Activity인 경우("Embedded App" 플래그)에도 Discord가 거부합니다. 이 오류는 리디렉션과는 관계가 없습니다.',
  streaming_discord_badsecret: 'Discord가 Client Secret을 거부했습니다. 개발자 포털에서 앱을 열어 시크릿을 재설정한 뒤 새 값을 자격 증명 편집에 붙여넣으세요.',
  streaming_discord_network: 'Discord는 승인했지만 이 PC가 로그인을 완료하기 위해 discord.com에 연결하지 못했습니다. VPN, 방화벽 또는 프록시 설정을 확인하고 다시 연결을 시도하세요.',
  streaming_discord_id_shape: 'Discord Client ID처럼 보이지 않습니다. 앱의 General Information 페이지에 "Application ID"로 표시된 긴 숫자입니다(Public Key나 Client Secret이 아닙니다).',
