  ra_guide_s1_body: '직접 켜기 전에는 꺼져 있습니다. 꺼져 있는 동안 Xenon은 이 PC에만 응답합니다.',
  ra_guide_s2: '휴대폰으로 QR 코드를 비춥니다',
  ra_guide_s2_body: '이 코드는 비밀번호가 아니라 초대장입니다. 3분 동안만 쓸 수 있고 몇 번 틀리면 사용할 수 없게 됩니다. 대시보드는 휴대폰 브라우저에서 열립니다. 휴대폰에 설치할 것은 없습니다.',
  ra_guide_s2_wait: '위의 스위치를 켜면 사용할 수 있습니다.',
  ra_guide_s3: '휴대폰 홈 화면에 추가합니다',
  ra_guide_s3_body: 'iPhone에서는 공유를 눌러 홈 화면에 추가를 선택합니다. Android에서는 Chrome이 설치를 제안합니다. 그러면 Xenon이 자체 아이콘으로 전체 화면에서 열리고, 마이크와 알림도 거기서 동작합니다.',
  ra_guide_s4: '보안 주소를 켭니다',
  ra_guide_s4_body: '이 PC에 어디서나 통하는 고유한 이름을 주고, 암호화된 연결로 연결합니다. 무료인 Tailscale을 쓰며 Xenon이 대신 설치하고 로그인합니다. Xenon 계정을 만드는 것이 아닙니다.',
  ra_guide_s5: 'Tailscale 계정에서 HTTPS 인증서를 켭니다',
  ra_guide_s5_body: 'Xenon이 대신 해 줄 수 없는 유일한 단계입니다. Tailscale 관리 콘솔을 열고 HTTPS Certificates까지 내려가 Enable을 누르세요. 모든 요금제에서 무료입니다. 그런 다음 여기로 돌아오면 Xenon이 계속 기다리고 있습니다.',
  ra_guide_s6: '휴대폰에 같은 계정으로 Tailscale을 설치합니다',
  ra_guide_s6_body: 'App Store나 Google Play에서 받아 방금 쓴 것과 같은 계정으로 로그인하고 스위치를 켜세요. 모두가 잊는 단계입니다. 빠지면 휴대폰이 주소를 아예 열 수 없다고 말합니다. 고장이 아니라, 그 주소가 내 네트워크 안에만 있기 때문입니다.',
  ra_guide_s7: '새 주소에서 휴대폰을 다시 연결합니다',
  ra_guide_s7_body: '2단계의 기기 추가를 누르고 다시 비추세요. 브라우저는 연결을 만들어진 주소에 묶기 때문에, 집 주소에서 연결한 휴대폰은 보안 주소에서는 연결되어 있지 않습니다. 이후에는 집에서도 밖에서도 새 주소만 쓰면 됩니다.',
  ra_guide_done_title: '설정이 끝났습니다',
  ra_guide_done_body: '휴대폰이 연결되었습니다. 마지막으로, Xenon이 이 PC에서도 계속 열려야 할까요?',
  ra_guide_keep: '이 PC에서도 계속',
  ra_guide_hide: '이 PC에서는 숨기기',
  ra_guide_hide_note: '숨기면 Xenon이 이 PC에서 열리지 않습니다. 로그인할 때도 마찬가지입니다. 백그라운드에서는 계속 실행되므로 휴대폰은 그대로 동작합니다. 시계 옆의 Xenon 아이콘이나 설정의 화면에서 창을 다시 불러올 수 있습니다.',
